// Version comparison logic
function compareVersions(v1, v2) {
  const [major1, minor1, patch1, pre1] = v1.split(/[-.]/);
  const [major2, minor2, patch2, pre2] = v2.split(/[-.]/);

  if (major1 !== major2) return major1 - major2;
  if (minor1 !== minor2) return minor1 - minor2;
  if (patch1 !== patch2) return patch1 - patch2;

  if (pre1 && !pre2) return -1; // Pre-release before stable
  if (!pre1 && pre2) return 1; // Stable after pre-release

  if (pre1 && pre2) {
    const preParts1 = pre1.split('.');
    const preParts2 = pre2.split('.');
    for (let i = 0; i < Math.max(preParts1.length, preParts2.length); i++) {
      const part1 = parseInt(preParts1[i], 10) || 0;
      const part2 = parseInt(preParts2[i], 10) || 0;
      if (part1 !== part2) return part1 - part2;
    }
  }

  return 0;
}

